/* Lot 90: font sizes that mix em with px, or use rem, resolved by the reader in px against the parent and root font sizes (generated by scripts/lot90_gen.py; expectations from that model). */

#include "../../framework/unity.h"
#include <string.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_o[1400];

static void prep(const char *html) { TEST_ASSERT_EQUAL(0, wf_site_prepare(&g_d, html, (int)strlen(html))); }

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) { wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o)); return g_o; }
    return "NO SUCH ID";
}

static int fs_of(const char *id) {
    int i;
    for (i = 0; i < g_d.nnodes; i++) if (!strcmp(g_d.node[i].id, id)) return g_d.fs[i];
    return -1;
}

static void test_l90_font_0(void) {
    prep("<html><head><style>html { font-size: 125% } #e0 { font-size: calc(1.2em + 0em) } #e0 { letter-spacing: calc(0.3em - 1px) }</style></head><body><div id=e0>x</div></body></html>");
    TEST_ASSERT_EQUAL(20000, g_d.root_fs);
    TEST_ASSERT_EQUAL(24000, fs_of("e0"));
    TEST_ASSERT_EQUAL_STRING(" style=\"font-size:1.2em;letter-spacing:6.2px\"", style_of("e0"));
}

static void test_l90_font_1(void) {
    prep("<html><head><style>html { font-size: 16px } #e0 { font-size: calc(1em + 0.25em) }</style></head><body><div id=e0>x</div></body></html>");
    TEST_ASSERT_EQUAL(16000, g_d.root_fs);
    TEST_ASSERT_EQUAL(20000, fs_of("e0"));
    TEST_ASSERT_EQUAL_STRING(" style=\"font-size:1.25em\"", style_of("e0"));
}

